for s in S: s['tot']=s['sc'][0]*2+s['sc'][1]*2+sum(s['sc'][2:])
S.sort(key=lambda s:-s['tot'])
for i,s in enumerate(S,1): s['r']=i
json.dump(S,open('run/shortlist.json','w'),indent=1,ensure_ascii=False)
for s in S:
    print(s['r'],s['tot'],s['t']); 
    for c in s['c']: print('   ',c['v'],c['s'],c['l'],'|',c['q'])
